test('recordLogin sets last_login_at to the current time on the active user', (t, done) => {
  const before = new Date().toISOString();
  recordLogin('ada@example.com', (err, user) => {
    assert.equal(err, null);
    assert.equal(user.id, 1);
    const after = new Date().toISOString();
    assert.ok(user.last_login_at >= before && user.last_login_at <= after);
    new UserRepository().findById(1).then((stored) => {
      assert.equal(stored.last_login_at, user.last_login_at);
      done();
    }, done);
  });
});

test('recordLogin ignores soft-deleted and unknown users', (t, done) => {
  recordLogin('alan@example.com', (err, user) => {
    assert.equal(err, null);
    assert.equal(user, null);
    new UserRepository().findById(3).then((alan) => {
      assert.equal(alan.last_login_at, undefined);
      recordLogin('nobody@example.com', (err2, none) => {
        assert.equal(err2, null);
        assert.equal(none, null);
        done();
      });
    }, done);
  });
});
EOF
